local CastingLadleSkimmerMaker = {}
local PRODUCTS = {
    iron_castingladleskimmer = { name = "Železni površinski strgalec zajemalk", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni površinski strgalec zajemalk za livarje." },
    bronze_castingladleskimmer = { name = "Bronast površinski strgalec zajemalk", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast površinski strgalec zajemalk za livarje." },
    silver_castingladleskimmer = { name = "Srebrn površinski strgalec zajemalk", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn površinski strgalec zajemalk za livarje." },
    gilded_castingladleskimmer = { name = "Pozlačen površinski strgalec zajemalk", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen površinski strgalec zajemalk za livarje." },
    jewel_set_castingladleskimmer = { name = "Draguljast površinski strgalec zajemalk", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast površinski strgalec zajemalk za livarje." },
    royal_sovereign_castingladleskimmer = { name = "Kraljevski suveren površinski strgalec zajemalk", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren površinski strgalec zajemalk z biseri za krono." },
}
local BUILDINGS = {
    castingladleskimmer_workshop = { name = "Castingladleskimmer delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    castingladleskimmer_house = { name = "Castingladleskimmer hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_castingladleskimmer_atelier = { name = "Mojstrski castingladleskimmer atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_castingladleskimmer_palace = { name = "Suverena castingladleskimmer palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CastingLadleSkimmerMaker.ironStock=18; CastingLadleSkimmerMaker.bronzeStock=14; CastingLadleSkimmerMaker.woodStock=10; CastingLadleSkimmerMaker.leatherStock=8; CastingLadleSkimmerMaker.silverStock=8; CastingLadleSkimmerMaker.goldStock=6; CastingLadleSkimmerMaker.jewelStock=4; CastingLadleSkimmerMaker.pearlStock=4
CastingLadleSkimmerMaker.productStock = {}; CastingLadleSkimmerMaker.buildings = {}; CastingLadleSkimmerMaker.maker = nil; CastingLadleSkimmerMaker.activeMaking = {}; CastingLadleSkimmerMaker.totalProducts = 0; CastingLadleSkimmerMaker.dayTimer = 0
function CastingLadleSkimmerMaker.init() CastingLadleSkimmerMaker.ironStock=18; CastingLadleSkimmerMaker.bronzeStock=14; CastingLadleSkimmerMaker.woodStock=10; CastingLadleSkimmerMaker.leatherStock=8; CastingLadleSkimmerMaker.silverStock=8; CastingLadleSkimmerMaker.goldStock=6; CastingLadleSkimmerMaker.jewelStock=4; CastingLadleSkimmerMaker.pearlStock=4; CastingLadleSkimmerMaker.productStock={}; CastingLadleSkimmerMaker.buildings={}; CastingLadleSkimmerMaker.maker=nil; CastingLadleSkimmerMaker.activeMaking={}; CastingLadleSkimmerMaker.totalProducts=0; CastingLadleSkimmerMaker.dayTimer=0; print("[CastingLadleSkimmerMaker] Royal Casting Ladle Skimmer Maker System initialized (6 products, 4 buildings)") end
function CastingLadleSkimmerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CastingLadleSkimmerMaker.maker={name=n or ("Strgar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strgar najet: %s (spretnost: %d)",CastingLadleSkimmerMaker.maker.name,s),"success") end; return true end
function CastingLadleSkimmerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CastingLadleSkimmerMaker.build(id) local ok,e=CastingLadleSkimmerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CastingLadleSkimmerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CastingLadleSkimmerMaker.getQualityBonus() local b=0; for _,bd in ipairs(CastingLadleSkimmerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CastingLadleSkimmerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CastingLadleSkimmerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CastingLadleSkimmerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CastingLadleSkimmerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CastingLadleSkimmerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CastingLadleSkimmerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CastingLadleSkimmerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CastingLadleSkimmerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CastingLadleSkimmerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CastingLadleSkimmerMaker.buildings==0 then return false,"Potrebna strgalna delavnica" end; if not CastingLadleSkimmerMaker.maker then return false,"Potreben strgar" end; return true end
function CastingLadleSkimmerMaker.make(pt,qty) qty=qty or 1; local ok,e=CastingLadleSkimmerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CastingLadleSkimmerMaker.ironStock=CastingLadleSkimmerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CastingLadleSkimmerMaker.bronzeStock=CastingLadleSkimmerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CastingLadleSkimmerMaker.woodStock=CastingLadleSkimmerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CastingLadleSkimmerMaker.leatherStock=CastingLadleSkimmerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CastingLadleSkimmerMaker.silverStock=CastingLadleSkimmerMaker.silverStock-d.silverCost*qty end; if d.goldCost then CastingLadleSkimmerMaker.goldStock=CastingLadleSkimmerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CastingLadleSkimmerMaker.jewelStock=CastingLadleSkimmerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CastingLadleSkimmerMaker.pearlStock=CastingLadleSkimmerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CastingLadleSkimmerMaker.maker then t=math.max(1,t-math.floor(CastingLadleSkimmerMaker.maker.skill/13)) end; table.insert(CastingLadleSkimmerMaker.activeMaking,{id="castingladleskimmer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CastingLadleSkimmerMaker.completeMaking(m) local q=1.0+(CastingLadleSkimmerMaker.getQualityBonus()/100); if CastingLadleSkimmerMaker.maker then q=q+(CastingLadleSkimmerMaker.maker.skill/140) end; q=math.min(2.5,q); CastingLadleSkimmerMaker.productStock[m.productType]=(CastingLadleSkimmerMaker.productStock[m.productType] or 0)+m.quantity; CastingLadleSkimmerMaker.totalProducts=CastingLadleSkimmerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CastingLadleSkimmerMaker.maker then CastingLadleSkimmerMaker.maker.itemsMade=CastingLadleSkimmerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CastingLadleSkimmerMaker.maker.skill=math.min(100,CastingLadleSkimmerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strgalnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"castingladleskimmer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CastingLadleSkimmerMaker.update(dt) if not _G.state then return end; CastingLadleSkimmerMaker.dayTimer=CastingLadleSkimmerMaker.dayTimer+dt; if CastingLadleSkimmerMaker.dayTimer>=30 then CastingLadleSkimmerMaker.dayTimer=0; for i=#CastingLadleSkimmerMaker.activeMaking,1,-1 do local m=CastingLadleSkimmerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CastingLadleSkimmerMaker.completeMaking(m); table.remove(CastingLadleSkimmerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CastingLadleSkimmerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CastingLadleSkimmerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CastingLadleSkimmerMaker.getStats() return {ironStock=CastingLadleSkimmerMaker.ironStock,bronzeStock=CastingLadleSkimmerMaker.bronzeStock,woodStock=CastingLadleSkimmerMaker.woodStock,leatherStock=CastingLadleSkimmerMaker.leatherStock,silverStock=CastingLadleSkimmerMaker.silverStock,goldStock=CastingLadleSkimmerMaker.goldStock,jewelStock=CastingLadleSkimmerMaker.jewelStock,pearlStock=CastingLadleSkimmerMaker.pearlStock,productStock=CastingLadleSkimmerMaker.productStock,numBuildings=#CastingLadleSkimmerMaker.buildings,hasMaker=CastingLadleSkimmerMaker.maker~=nil,makerName=CastingLadleSkimmerMaker.maker and CastingLadleSkimmerMaker.maker.name or "—",makerSkill=CastingLadleSkimmerMaker.maker and CastingLadleSkimmerMaker.maker.skill or 0,activeMaking=#CastingLadleSkimmerMaker.activeMaking,totalProducts=CastingLadleSkimmerMaker.totalProducts} end
return CastingLadleSkimmerMaker
